import sys

MOD = 998244353

def main():
    W, H, L, R, D, U = map(int, sys.stdin.readline().split())

    max_n = W + H + 4
    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (max_n + 1)
    invfact[max_n] = pow(fact[max_n], MOD - 2, MOD)
    for i in range(max_n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD

    # Sum_{0<=x<=a,0<=y<=b} C(x+y+2, x+1)
    def pref_c(a, b):
        if a < 0 or b < 0:
            return 0
        return (C(a + b + 4, a + 2) - a - b - 4) % MOD

    def rect_c(x1, x2, y1, y2):
        if x1 > x2 or y1 > y2:
            return 0
        return (
            pref_c(x2, y2)
            - pref_c(x1 - 1, y2)
            - pref_c(x2, y1 - 1)
            + pref_c(x1 - 1, y1 - 1)
        ) % MOD

    # Number of all monotone paths in a full rectangle [0..a] x [0..b].
    def all_paths(a, b):
        return (pref_c(a, b) - (a + 1) * (b + 1)) % MOD

    hole_area = (R - L + 1) * (U - D + 1) % MOD

    total = all_paths(W, H)

    # Full-grid paths whose endpoint is in the removed rectangle.
    end_in_hole = (rect_c(L, R, D, U) - hole_area) % MOD

    # Full-grid paths whose startpoint is in the removed rectangle,
    # transformed by reversing coordinates.
    start_in_hole = (
        rect_c(W - R, W - L, H - U, H - D) - hole_area
    ) % MOD

    # Paths with both endpoints in the removed rectangle were subtracted twice.
    both_in_hole = all_paths(R - L, U - D)

    valid_endpoints_paths = (total - start_in_hole - end_in_hole + both_in_hole) % MOD

    invalid = 0

    # First entry into the hole from the left edge.
    if L > 0:
        for y in range(D, U + 1):
            prefix = (C(L + y + 1, L) - 1) % MOD
            suffix_all = (C((W - L) + (H - y) + 2, W - L + 1) - 1) % MOD
            suffix_inside = (C((R - L) + (U - y) + 2, R - L + 1) - 1) % MOD
            invalid = (invalid + prefix * ((suffix_all - suffix_inside) % MOD)) % MOD

    # First entry into the hole from the bottom edge.
    if D > 0:
        for x in range(L, R + 1):
            prefix = (C(x + D + 1, x + 1) - 1) % MOD
            suffix_all = (C((W - x) + (H - D) + 2, W - x + 1) - 1) % MOD
            suffix_inside = (C((R - x) + (U - D) + 2, R - x + 1) - 1) % MOD
            invalid = (invalid + prefix * ((suffix_all - suffix_inside) % MOD)) % MOD

    print((valid_endpoints_paths - invalid) % MOD)

